const compressedImages = {
  "43": "",
  "50": ""
} as const;

export function canonicalLoginLedgerDatabaseBytes(version: 43 | 50): Uint8Array {
  const fixture = canonicalLoginLedgerFixtures[version];
  const recipe = readFileSync(new URL("./canonical-login-ledger-generator.original.ts.txt", import.meta.url));
  if (createHash("sha256").update(recipe).digest("hex") !== fixture.generatorSha256) {
    throw new Error("Canonical login/ledger generator integrity mismatch.");
  }
  const bytes = gunzipSync(Buffer.from(compressedImages[version], "base64"), {
    maxOutputLength: fixture.databaseBytes,
  });
  if (bytes.length !== fixture.databaseBytes
    || createHash("sha256").update(bytes).digest("hex") !== fixture.databaseSha256) {
    throw new Error("Canonical login/ledger fixture integrity mismatch.");
  }
  return Uint8Array.from(bytes);
}
